  async function renderPremiumPackages() { const panel = $('premiumPackages'), list = $('premiumPackagesList'), status = $('premiumPackagesStatus'); if (!panel || !list) return; if (activeGameShop) { panel.hidden = true; return; } panel.hidden = false; if (status) status.textContent = 'Загрузка Gems-пакетов…'; try { const packages = await window.TelePlayCore?.PaymentManager?.packages?.() || []; if (!packages.length) { if (status) status.textContent = 'Пакеты Stars пока недоступны.'; list.innerHTML = '<div class="shop-empty premium-packages-empty">Не удалось получить Gems-пакеты с сервера.<br><button type="button" class="premium-retry" data-premium-retry>Повторить загрузку</button></div>'; return; } if (status) status.textContent = 'Выбери пакет — оплата откроется внутри Telegram.'; list.innerHTML = packages.map(item => { const totalGems = Number(item.totalGems ?? Number(item.gemsAmount || 0) + Number(item.bonus || 0)); const bonus = Number(item.bonus || 0); return `<button type="button" class="secondary-button premium-package" data-premium-package="${item.id}"><b>${format(totalGems)} 💎</b><span>${format(item.amount)} ${item.currency}${bonus ? ` · +${format(bonus)} бонус` : ''}</span></button>`; }).join(''); } catch (_) { if (status) status.textContent = 'Не удалось загрузить Gems-пакеты.'; list.innerHTML = '<div class="shop-empty premium-packages-empty">Проверь подключение и повтори загрузку.<br><button type="button" class="premium-retry" data-premium-retry>Повторить загрузку</button></div>'; } }
