  function updateCatalogStats() { const data = player()?.get?.(); if (data) renderDashboard(data); window.NeonRaceGame?.updateCatalog?.(); }
  function setCategory(category) { if (!categories[category]) return; document.querySelectorAll('.tab').forEach(tab => { const active = tab.dataset.category === category; tab.classList.toggle('active', active); tab.setAttribute('aria-pressed', String(active)); }); const visible = games.filter(game => category === 'all' || game.category === category); $('gameGrid').innerHTML = visible.map(GameCard).join(''); $('sectionTitle').textContent = category === 'all' ? 'Все игры' : categories[category]; $('sectionCount').textContent = `${visible.length} ${visible.length === 1 ? 'игра' : visible.length < 5 ? 'игры' : 'игр'}`; $('emptyState').hidden = visible.length > 0; }
